typescript_example:
// TypeScript example (pseudocode)
import { RedwoodClient, retryPresets } from '@redwood/sdk'
const client = new RedwoodClient({ retryPreset: retryPresets.safe })
// attach idempotency key provided by caller
const idKey = generateUUID()
await client.post('/v1/charge', { body: payload, headers: { 'Idempotency-Key': idKey } })
// streaming resume
let state: any = { lastSeq: 0, resumeToken: null }
const stream = client.stream('/v1/events')
stream.on('data', (chunk) => { process(chunk); state.lastSeq = chunk.seq; state.resumeToken = chunk.resume_token })
stream.on('end', () => console.log('stream ended'))
// on reconnect
await client.resumeStream('/v1/events/resume', { resumeToken: state.resumeToken, lastSeq: state.lastSeq })

go_example:
// Go example (pseudocode)
import (
  "context"
  "github.com/redwood/redwood-go"
)
client := redwood.NewClient(redwood.WithRetryPreset(redwood.RetrySafe))
// idempotency key helper
idKey := client.GenerateIdempotencyKey(nil, "uuid")
_, err := client.Post(context.Background(), "/v1/charge", payload, redwood.WithHeader("Idempotency-Key", idKey))
// streaming resume
state := map[string]interface{}{}
stream, _ := client.Stream(context.Background(), "/v1/events")
for stream.Next() { chunk := stream.Message(); process(chunk); state["last_seq"] = chunk.Seq; state["resume_token"] = chunk.ResumeToken }
client.ResumeStream(context.Background(), "/v1/events/resume", state["resume_token"].(string), int64(state["last_seq"].(int)))
